    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);recordsFactory=Records.factory;settingsFactory=RhythmSettings.factory;if(state!=null){saved=state.getInt("saved",31);draft=state.getInt("draft",31);editing=state.getBoolean("editing");token=state.getString("token");failure=state.getString("failure","");restoredDraft=true;selectedRecord=state.getLong("selectedRecord");selectedDay=state.getString("selectedDay","");selectionNotice=state.getString("selectionNotice","");rhythmPosition=Math.max(0,state.getInt("rhythmPosition"));workdayPosition=Math.max(0,state.getInt("workdayPosition"));evidence=!editing&&state.getBoolean("evidence");evidenceOffset=Math.max(0,state.getInt("evidenceOffset"));evidencePosition=Math.max(0,state.getInt("evidencePosition"));}render();}
