    private void load(){int request=++generation;int cutoff=Math.max(0,Math.min(1439,Prefs.number(this,"statsCutoff",0)));long now=clock.getAsLong();Context app=getApplicationContext();Records.Factory scope=recordsFactory;RhythmSettings.Factory settings=settingsFactory;reader.execute(()->{try(Store store=scope.open(app)){List<RecordEntry> result=Records.all(store);int workdays=RhythmSettings.read(settings.open(app));RhythmStats resultStats=new RhythmStats(result,cutoff,workdays,now);runOnUiThread(()->{if(isDestroyed()||request!=generation)return;stats=resultStats;if(selectedRecord>0&&selectedNight()==null){selectedRecord=0;selectedDay="";selectionNotice="The selected night is no longer in this view. Choose another plotted night.";}if(!restoredDraft&&!editing&&token==null){saved=draft=workdays;}restoredDraft=false;loaded=true;if(token==null&&!editing)failure="";render();});}catch(Exception error){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;failure=error.getMessage()==null?"Your sleep records could not be opened.":error.getMessage();loaded=false;render();});}});}
