        PlanActivity.detail(body,"calendar","Reviewed sleep regularity","Complete-day diary confirmations",null,()->{owned.dismiss();startActivity(RecordUi.intent(this,SRIActivity.class));});
        PlanActivity.detail(body,"clock","Self-reported timing","Calculate from your usual sleep times",null,()->{owned.dismiss();startActivity(RecordUi.intent(this,HabitualTimingActivity.class));});
