        PlanActivity.detail(body,"info","About these records",null,null,()->{owned.dismiss();message("Recorded periods","The latest seven available main nights are shown with their dates. Each sleep-day uses its longest closed, untagged-nap period of at least three recorded hours, matching History. Pauses and awake edits are excluded from coverage; edge edits trim the plotted period. Manual periods are user-reported. Bedtime range uses the shortest interval around the 24-hour clock. Midpoints use elapsed time between the effective period boundaries, not sleep-stage estimates.");});
        Design.button(body,"Done",false,owned::dismiss);ScrollView scroll=new ScrollView(this);scroll.addView(body);owned.setContentView(scroll);owned.show();Window window=owned.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-Design.dp(this,32),Design.dp(this,440)),-2);window.setGravity(Gravity.BOTTOM);}dialog=owned;
