    private void heading(LinearLayout body,String text,String description,Runnable action){LinearLayout row=Design.row(this);row.addView(Design.text(this,text,16,600,Design.INK),new LinearLayout.LayoutParams(-2,-2));View info=Design.iconButton(this,"info",description,action);info.setPadding(Design.dp(this,15),Design.dp(this,15),Design.dp(this,15),Design.dp(this,15));row.addView(info,new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(row);}
    private void group(LinearLayout col,String text,int count,Double mean,int color){LinearLayout row=Design.row(this),copy=Design.col(this);View dot=new View(this);dot.setBackground(Design.shape(this,color,6));LinearLayout.LayoutParams mark=new LinearLayout.LayoutParams(Design.dp(this,12),Design.dp(this,12));mark.setMargins(0,Design.dp(this,2),Design.dp(this,8),0);mark.gravity=Gravity.TOP;row.addView(dot,mark);Design.text(copy,text+" ("+count+")",11,400,Design.MUTED);Design.space(copy,2);Design.text(copy,mean==null?"—":RhythmChart.label(this,mean),16,600,Design.INK);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));col.addView(row);}
    private void progress(LinearLayout body,int nights){FrameLayout track=new FrameLayout(this);track.setBackground(Design.shape(this,NightDialTokens.RULE,12));View fill=new View(this);fill.setBackground(Design.shape(this,Design.VIOLET,12));track.addView(fill,new FrameLayout.LayoutParams(0,-1));track.setContentDescription("Recorded-night history progress "+nights+" of 30");track.addOnLayoutChangeListener((v,a,b,c,d,e,f,g,h)->{ViewGroup.LayoutParams p=fill.getLayoutParams();int width=Math.round(track.getWidth()*Math.min(30,nights)/30f);if(p.width!=width){p.width=width;fill.setLayoutParams(p);}});body.addView(track,new LinearLayout.LayoutParams(-1,Design.dp(this,12)));}
    private void workdays(LinearLayout body){Design.space(body,12);Design.text(body,"Choose the days you wake for work or school.",14,400,Design.MUTED);Design.space(body,10);for(int day=1;day<=7;day++){int bit=1<<(day-1);Design.toggle(body,DayOfWeek.of(day).getDisplayName(TextStyle.FULL,Locale.getDefault()),null,(draft&bit)!=0,on->{if(on)draft|=bit;else draft&=~bit;});Design.line(body);}Design.space(body,10);Design.text(body,"Unselected days are free days. A fixed weekly schedule may not describe shift work.",12,400,Design.MUTED);if(!failure.isEmpty())Design.text(body,failure,13,500,NightDialTokens.NEGATIVE);Design.button(RecordUi.footer(body),token==null?"Save workdays":"Saving…",true,this::save);if(token!=null)RecordUi.enabled(body,false);}
    private String summary(int mask){if(mask==0)return "No workdays";if(mask==127)return "Every day";List<String> days=new ArrayList<>();for(int n=1;n<=7;n++)if((mask&(1<<(n-1)))!=0)days.add(DayOfWeek.of(n).getDisplayName(TextStyle.NARROW,Locale.getDefault()));return String.join(" · ",days);}
    private void message(String title,String text){if(dialog!=null&&dialog.isShowing())return;dialog=SleepPicker.message(this,title,text);}
    private void save(){if(token!=null)return;token=UUID.randomUUID().toString();failure="";render();observeSave();}
    private void observeSave(){if(!resumed||token==null)return;int value=draft,expected=saved;RhythmSettings.Factory scope=settingsFactory;PlanOperations.Operation operation=PlanOperations.start(this,token,app->{RhythmSettings.save(scope.open(app),value,expected);return null;});if(!operation.done){handler.postDelayed(observe,75);return;}PlanOperations.forget(token);token=null;if(operation.error==null){saved=draft;editing=false;failure="";loaded=false;load();}else failure=operation.error;render();}
    private void back(){if(token!=null)return;if(evidence){rememberPosition();evidence=false;render();return;}if(editing){draft=saved;editing=false;failure="";loaded=false;load();render();}else finish();}
    @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
    @Override protected void onSaveInstanceState(Bundle state){rememberPosition();super.onSaveInstanceState(state);state.putLong("selectedRecord",selectedRecord);state.putString("selectedDay",selectedDay);state.putString("selectionNotice",selectionNotice);state.putBoolean("evidence",evidence);state.putInt("evidenceOffset",evidenceOffset);state.putInt("evidencePosition",evidencePosition);state.putInt("rhythmPosition",rhythmPosition);state.putInt("workdayPosition",workdayPosition);state.putInt("saved",saved);state.putInt("draft",draft);state.putBoolean("editing",editing);state.putString("token",token);state.putString("failure",failure);}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeout)throws Exception{if(reader.isShutdown()){if(!reader.awaitTermination(timeout,TimeUnit.MILLISECONDS))throw new TimeoutException("Rhythm readers still active");}else reader.submit(()->{}).get(timeout,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){generation++;handler.removeCallbacksAndMessages(null);if(dialog!=null)dialog.dismiss();reader.shutdownNow();super.onDestroy();}
